/* ── 家庭账号（可选） ───────────────────────────────────
 * 方案 A：账号服务只做身份和路由，故事正文不经过它，也没有任何存档。
 * 登录后由后端下发这台板子专属的 broker 账号和 topic，浏览器仍然直连
 * broker —— 和以前一样，只是不再所有家庭共用一条 kb086/out。
 * 后端不可用时页面照常工作，点「先手动连接」就是老路子。 */

var acct = null;      /* {account, family, devices} */
var gateReg = false;  /* 闸门当前是注册还是登录 */

function api(path, opt){
  opt = opt || {};
  opt.credentials = 'same-origin';
  if (opt.body && typeof opt.body !== 'string'){
    opt.body = JSON.stringify(opt.body);
    opt.headers = Object.assign({'Content-Type':'application/json'}, opt.headers || {});
  }
  return fetch(path, opt).then(function(r){
    return r.text().then(function(t){
      var j = {};
      try { j = t ? JSON.parse(t) : {}; } catch(e){}
      if (!r.ok){
        var err = new Error(j.error || ('HTTP ' + r.status));
        err.status = r.status;
        throw err;
      }
      return j;
    });
  });
}

function gateMsg(text){ $('gateMsg').textContent = text || ''; }

function showGate(text){
  gateMsg(text);
  $('gate').style.display = 'flex';
}

function hideGate(){ $('gate').style.display = 'none'; }

function gateMode(mode){
  gateReg = (mode === 'register');
  $('gateTitle').textContent = gateReg ? '注册家庭账号' : '登录家长账号';
  $('gateSub').textContent = gateReg
    ? '每个家庭一个账号。注册后先添加一台板子，再把生成的命令在板子上执行一次。'
    : '登录后自动带出你家的板子和专属连接参数。';
  $('gateFamilyField').style.display = gateReg ? '' : 'none';
  $('gateSubmit').textContent = gateReg ? '注册并登录' : '登录';
  $('gateSwitch').textContent = gateReg ? '已有账号，去登录' : '注册新家庭';
  $('gateSwitch').onclick = function(){ gateMode(gateReg ? 'login' : 'register'); return false; };
  gateMsg('');
}

function gateSubmit(){
  var email = $('gateEmail').value.trim();
  var pw = $('gatePassword').value;
  if (!email || !pw){ gateMsg('邮箱和口令都要填'); return; }
  if (gateReg && pw.length < 8){ gateMsg('口令至少 8 位'); return; }
  var body = { email: email, password: pw };
  if (gateReg) body.family_name = $('gateFamily').value.trim() || '我的家';
  $('gateSubmit').disabled = true;
  api(gateReg ? '/api/register' : '/api/login', { method:'POST', body: body })
    .then(function(){
      $('gatePassword').value = '';
      hideGate();
      return refreshMe();
    })
    .catch(function(e){ gateMsg(e.message); })
    .then(function(){ $('gateSubmit').disabled = false; });
}

function gateSkip(){
  hideGate();
  renderMsg('未登录，按手动连接使用。填好下面的 Broker 地址点「连接」。', 'sys');
}

function logout(){
  api('/api/logout', { method:'POST' }).catch(function(){}).then(function(){
    try { localStorage.removeItem('kb.lastDevice'); } catch(e){}
    location.reload();
  });
}

function refreshMe(){
  return api('/api/me').then(function(j){
    acct = j;
    renderAcct();
    var last = '';
    try { last = localStorage.getItem('kb.lastDevice') || ''; } catch(e){}
    var hit = (j.devices || []).filter(function(d){ return d.id === last; })[0];
    if (hit) useDevice(hit.id, true);
  });
}

