/* silent=true：开机恢复时只填参数不连，免得一打开页面就往外连 */
function useDevice(id, silent){
  api('/api/devices/' + id + '/provision', { method:'POST' }).then(function(j){
    applyDevice(j);
    if (!silent) log('已带出「' + j.device.name + '」的连接参数，点「连接」即可。', 'sys');
  }).catch(function(e){ log('账号服务：' + e.message, 'sys'); });
}

function applyDevice(j){
  $('brokerUrl').value = j.broker.url;
  $('username').value  = j.broker.username;
  $('password').value  = j.broker.password;
  $('topicIn').value   = j.broker.topic_in;
  $('topicOut').value  = j.broker.topic_out;
  if (!$('chatId').value.trim()) $('chatId').value = 'parent';
  try { localStorage.setItem('kb.lastDevice', j.device.id); } catch(e){}
  saveSettings();   /* 口令不落盘 */
}

function addDevice(){
  var name = ($('newDevName').value || '').trim() || '我的板子';
  api('/api/devices', { method:'POST', body:{ name:name } }).then(function(j){
    $('newDevName').value = '';
    $('provBox').style.display = '';
    $('provCmd').textContent = j.command;
    refreshMe();
  }).catch(function(e){ log('账号服务：' + e.message, 'sys'); });
}

function rotateDevice(id){
  if (!confirm('换密码之后，板子和手机都要用新命令重新配置。继续？')) return;
  api('/api/devices/' + id + '/rotate', { method:'POST' }).then(function(j){
    $('provBox').style.display = '';
    $('provCmd').textContent = j.command;
    if (acct && acct.devices.filter(function(d){ return d.id === id; })[0]){
      var cur = localStorage.getItem('kb.lastDevice');
      if (cur === id) applyDevice(j);   /* 正在用的这台，直接换上新口令 */
    }
    log('设备密码已更换，记得在板子上重新执行命令。', 'sys');
  }).catch(function(e){ log('账号服务：' + e.message, 'sys'); });
}

function removeDevice(id, name){
  if (!confirm('删除「' + name + '」？板子上的连接会失效。')) return;
  api('/api/devices/' + id, { method:'DELETE' }).then(function(){
    var cur = localStorage.getItem('kb.lastDevice');
    if (cur === id){ try { localStorage.removeItem('kb.lastDevice'); } catch(e){} }
    refreshMe();
  }).catch(function(e){ log('账号服务：' + e.message, 'sys'); });
}

function copyProv(){
  var text = $('provCmd').textContent || '';
  if (!text) return;
  if (navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(function(){
      renderMsg('命令已复制。', 'sys');
    }).catch(function(){ selectProv(); });
  } else {
    selectProv();
  }
}

function selectProv(){
  var r = document.createRange();
  r.selectNodeContents($('provCmd'));
  var sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(r);
  renderMsg('已选中命令，手动复制即可。', 'sys');
}

